import sys

def search(S, pat):
    n = len(S)
    m = len(pat)
    if m == 0 or n < m:
        return []

    # Compute LPS array for KMP
    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if pat[i] == pat[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    result = []
    i = 0  # index for S
    j = 0  # index for pat
    while i < n:
        if pat[j] == S[i]:
            i += 1
            j += 1

        if j == m:
            # Found occurrence at index i - j (0-based)
            result.append(i - j + 1)  # Convert to 1-based
            j = lps[j - 1]

        elif i < n and pat[j] != S[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return result

if __name__ == "__main__":
    data = sys.stdin.read().splitlines()
    if len(data) >= 2:
        S = data[0].strip()
        pat = data[1].strip()
        ans = search(S, pat)
        if not ans:
            print(-1)
        else:
            print(*(ans))
    else:
        print(-1)
